def backlog_profile(rate_produce, rate_consume, initial=0):
    """返回 (能否清空, 清空时间)。drain_time 为 None 表示不会自动清空。"""
    net = rate_produce - rate_consume
    if net > 0:
        return False, None
    if net == 0:
        return initial == 0, None
    return True, initial / (-net)


